      { lv: 2, text: "The roots of x² − px + 12 = 0 differ by 1, and p > 0. Find p.", fmt: "TITA", ans: {"kind":"num","v":7}, show: "7", type: "Roots with a condition", steps: ["Two numbers with product 12 that differ by 1: 3 and 4.","p = sum = 7."] },
      { lv: 2, text: "A pen and a notebook cost ₹35 together. 3 pens and 2 notebooks cost ₹85. What does a notebook cost?", fmt: "TITA", ans: {"kind":"num","v":20}, show: "₹20", type: "Word problem (linear)", steps: ["p + n = 35 → 3p + 3n = 105.","Subtract 3p + 2n = 85: n = 20."] },
      { lv: 2, text: "Two numbers add up to 25 and differ by 7. Find the larger.", fmt: "TITA", ans: {"kind":"num","v":16}, show: "16", type: "Two linear equations", steps: ["(25 + 7)/2 = 16."] },
      { lv: 2, text: "One root of x² − kx + 12 = 0 is 3. Find k.", fmt: "TITA", ans: {"kind":"num","v":7}, show: "7", type: "Roots with a condition", steps: ["9 − 3k + 12 = 0 → k = 7."] },
      { lv: 2, text: "A father is 4 times as old as his son. In 20 years he will be twice as old. How old is the son now?", fmt: "TITA", ans: {"kind":"num","v":10}, show: "10 years", type: "Word problem (linear)", steps: ["4s + 20 = 2(s + 20) → 2s = 20 → s = 10."] },
      { lv: 2, text: "How many real roots does x² + 4x + 7 = 0 have?", fmt: "TITA", ans: {"kind":"num","v":0}, show: "0", type: "Discriminant", steps: ["D = 16 − 28 < 0 → no real roots."] },
      { lv: 2, text: "A number greater than 1, added to its reciprocal, gives 10/3. Find the number.", fmt: "TITA", ans: {"kind":"num","v":3}, show: "3", type: "Quadratic word problem", steps: ["x + 1/x = 10/3 → 3x² − 10x + 3 = 0 → x = 3 or 1/3.","Greater than 1 → 3."] },
      { lv: 3, text: "How many positive whole-number solutions does 4x + 7y = 100 have?", fmt: "TITA", ans: {"kind":"num","v":3}, show: "3", type: "Whole-number solutions", steps: ["7y must leave 100 divisible by 4 → y is a multiple of 4.","y = 4 → x = 18; y = 8 → x = 11; y = 12 → x = 4; y = 16 → x < 0.","3 solutions."] },
      { lv: 3, text: "α and β are the roots of x² − 5x + 3 = 0. Find α² + β².", fmt: "TITA", ans: {"kind":"num","v":19}, show: "19", type: "Symmetric expressions of roots", steps: ["α + β = 5, αβ = 3.","α² + β² = (α + β)² − 2αβ = 25 − 6 = 19."] },
      { lv: 3, text: "x² + kx + 9 > 0 for every real x. Which is true?", fmt: "MCQ", opts: ["(a) −6 < k < 6","(b) k > 6","(c) k < −6","(d) k = ±6"], ans: {"kind":"mcq","v":"a"}, show: "(a) −6 < k < 6", type: "Discriminant", steps: ["Always positive → no real roots → D < 0.","k² − 36 < 0 → −6 < k < 6."] },
      { lv: 3, text: "How many pairs of positive integers (x, y) satisfy 1/x + 1/y = 1/4?", fmt: "TITA", ans: {"kind":"num","v":5}, show: "5", type: "Whole-number solutions", steps: ["Rearrange: (x − 4)(y − 4) = 16.","Positive factor pairs of 16: (1,16), (2,8), (4,4), (8,2), (16,1) → 5."] },
      { lv: 3, text: "The roots of x² + px + q = 0 are 2 and 5. What is the sum of the roots of x² + qx + p = 0?", fmt: "TITA", ans: {"kind":"num","v":-10}, show: "−10", type: "Sum and product of roots", steps: ["p = −7, q = 10.","Second equation: sum = −q = −10."] },
      { lv: 3, text: "For what m are the roots of x² − 2mx + m + 6 = 0 real and equal?", fmt: "MCQ", opts: ["(a) 3 only","(b) −2 only","(c) 3 or −2","(d) 2 or −3"], ans: {"kind":"mcq","v":"c"}, show: "(c) 3 or −2", type: "Discriminant", steps: ["D = 4m² − 4(m + 6) = 0 → m² − m − 6 = 0 → m = 3 or −2."] }
